// CUDA WebShader 0.1.1. Generated from kernel water_norm.
@group(0) @binding(0) var<storage, read> b_rows: array<f32>;
@group(0) @binding(1) var<storage, read_write> b_scales: array<f32>;
const cw_block_size: vec3<u32> = vec3<u32>(128u, 1u, 1u);

fn cw_divide_f32(a: f32, b: f32) -> f32 { let q = a / b; if ((bitcast<u32>(q) & 0x7f800000u) == 0x7f800000u || (bitcast<u32>(q) & 0x7fffffffu) == 0u || (bitcast<u32>(b) & 0x7f800000u) == 0x7f800000u) { return q; } let residual = fma(-q, b, a); return q + residual / b; }

alias cw_f64 = vec2<u32>;










struct CWDoubleParts { significand: vec2<u32>, exponent: i32, }

// Input has its leading bit at bit 55 and three guard/round/sticky bits.














// Restoring square root: 56 root bits include guard/round/sticky for binary64.


















































@compute @workgroup_size(128, 1, 1)
fn main(
  @builtin(local_invocation_id) cw_thread: vec3<u32>,
  @builtin(workgroup_id) cw_block: vec3<u32>,
  @builtin(num_workgroups) cw_grid: vec3<u32>
) {
  var v_c: i32 = i32(((cw_block.x * cw_block_size.x) + cw_thread.x));
  if ((v_c >= 2i)) {
    return;
  }
  var v_sum: f32 = 0.0f;
  {
    var v_z: i32 = 0i;
    loop {
      if (!(v_z < 64i)) { break; }
      v_sum = (v_sum + b_rows[((v_c * 64i) + v_z)]);
      continuing {
        v_z += i32(1);
      }
    }
  }
  var cw_tmp_3: f32;
  if ((v_c == 0i)) {
    cw_tmp_3 = 0.12f;
  } else {
    cw_tmp_3 = 0.065f;
  }
  b_scales[v_c] = cw_divide_f32(cw_tmp_3, sqrt(max(1e-7f, v_sum)));
}
